147			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
148		}
149		if currentUser == nil || currentUser.ID != userID {
150			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
151		}
152	
153		newShortcut := &storepb.ShortcutsUserSetting_Shortcut{
154			Id:     util.GenUUID(),
155			Title:  request.Shortcut.GetTitle(),
156			Filter: request.Shortcut.GetFilter(),
157		}
158		if newShortcut.Title == "" {
159			return nil, status.Errorf(codes.InvalidArgument, "title is required")
160		}
161		if err := s.validateFilter(ctx, newShortcut.Filter); err != nil {
162			return nil, status.Errorf(codes.InvalidArgument, "invalid filter: %v", err)
163		}
164		if request.ValidateOnly {
165			return &v1pb.Shortcut{
166				Name:   constructShortcutName(user.Username, newShortcut.GetId()),
167				Title:  newShortcut.GetTitle(),
168				Filter: newShortcut.GetFilter(),
169			}, nil
170		}
171	
172		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
173			UserID: &userID,
174			Key:    storepb.UserSetting_SHORTCUTS,
175		})
176		if err != nil {
177			return nil, err
178		}
179		if userSetting == nil {
180			userSetting = &storepb.UserSetting{
181				UserId: userID,
182				Key:    storepb.UserSetting_SHORTCUTS,
183				Value: &storepb.UserSetting_Shortcuts{
184					Shortcuts: &storepb.ShortcutsUserSetting{
185						Shortcuts: []*storepb.ShortcutsUserSetting_Shortcut{},
186					},
187				},
188			}
189		}
190		shortcutsUserSetting := userSetting.GetShortcuts()
191		shortcuts := shortcutsUserSetting.GetShortcuts()
192		shortcuts = append(shortcuts, newShortcut)
193		shortcutsUserSetting.Shortcuts = shortcuts
194	
195		userSetting.Value = &storepb.UserSetting_Shortcuts{
196			Shortcuts: shortcutsUserSetting,
197		}
198	
199		_, err = s.Store.UpsertUserSetting(ctx, userSetting)
200		if err != nil {
201			return nil, status.Errorf(codes.Internal, "failed to upsert user setting: %v", err)
202		}
203	
204		return &v1pb.Shortcut{
205			Name:   constructShortcutName(user.Username, newShortcut.GetId()),
206			Title:  newShortcut.GetTitle(),
207			Filter: newShortcut.GetFilter(),
